  ('outfielder-shoulder-hamstring-care', 1, 3, 'outfielder-shoulder-hamstring-care-b', 'Hamstrings · Activate'),
  ('outfielder-shoulder-hamstring-care', 1, 5, 'outfielder-shoulder-hamstring-care-c', 'Hips & Ankles · Activate'),
