  ) as v(plan_slug, week_number, day_number, wslug, title)
  join public.plans p on p.slug = v.plan_slug
  join public.workouts w on w.slug = v.wslug
  where pw.plan_id = p.id and pw.week_number = v.week_number and pw.day_number = v.day_number;
  get diagnostics n = row_count;
  if n <> 840 then raise exception 'expected 840 plan_workouts rows updated, updated %', n; end if;

  -- 4. plan descriptions (and the two retitled plans)
  update public.plans p
  set description = v.description, name = coalesce(v.new_name, p.name)
  from (values
  ('qb-escape-scramble-speed', 'Sprint work for the quarterback who has to beat a collapsing pocket. Short accelerations out of the drop, curved escape sprints, and posterior-chain power that transfers to scrambling, with hamstring insurance built in. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('qb-off-season-foundations', 'The base-building block for a quarterback: total-body strength, a healthy upper back, and rotational power that feeds the throw. Lower-body lifts build the drive leg; med-ball and landmine work teach the hips to lead the shoulders. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', 'QB Rotational Power & Strength Foundations'),
  ('qb-pocket-footwork-agility', 'Footwork is the quarterback''s first skill. This block drills drop-back mechanics, pocket slides and escape cuts, then layers in lower-body elasticity so the feet stay quick and the base stays balanced when throwing under pressure. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('qb-game-speed-conditioning', 'Conditioning built around how a quarterback actually plays: bursts of activity between long recoveries, capped by two-minute-drill repeats. Tempo runs, bike intervals and short sprints build the engine without beating up the arm or hamstrings. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('qb-shoulder-hip-care', 'Throwing-arm insurance and hip mobility for the quarterback. Rotator cuff and scapular work protect the shoulder, while hip and thoracic mobility let the trunk rotate freely so the arm isn''t asked to do the work of the body. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('wr-speed-acceleration-plan', 'Linear speed for the receiver: start mechanics off the line, acceleration into the stem, and top-end velocity to run away from corners. Heavy emphasis on sprint volume with full rest, elastic plyometrics and hamstring durability. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('wr-release-power-strength', 'Strength and power for winning at the line and at the catch point. Olympic-style pulls and squats build explosive legs, upper-body pressing and pulling handle press coverage and contested balls, and single-leg work keeps the base sound. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('wr-route-break-agility', 'Get in and out of breaks faster than the defender can react. Plant-and-cut mechanics, reactive cuts, and deceleration training so the receiver can stop hard, change direction, and re-accelerate without losing speed. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('wr-route-tree-conditioning', 'Repeat-effort conditioning for running a full route tree play after play. Gassers, repeat sprints and bike intervals build the ability to hit top speed on the last snap of the drive, not just the first. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('wr-hamstring-ankle-care', 'Keep the wheels healthy. Eccentric hamstring work, ankle stiffness and calf strength, and hip and groin mobility target the soft-tissue injuries that most often sideline sprinters and cutters. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('ol-first-step-acceleration', 'Linemen win in the first five yards. Short, violent starts, sled work for drive-phase mechanics and heavy-hips power training build the explosive first step off the snap rather than long-distance speed. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('ol-strength-foundations-plan', 'The lineman''s foundation: squat, press and pull heavy, build the trunk and grip to anchor against rushers, and add sled and carry work for real-world strength. Low-rep, high-rest sets prioritize maximal force. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('ol-pass-set-redirect-agility', 'Short-area lateral quickness for pass protection: kick-slide footwork, mirroring rushers, and redirecting a heavy frame without losing your base. Emphasis on staying low, keeping the feet under the hips and re-anchoring on contact. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('ol-drive-phase-conditioning', 'Conditioning for a position that is 200-plus pounds of repeated short, violent effort. Sled work mimics the drive phase, while carries and low-impact intervals build the engine without pounding the joints. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('ol-hip-knee-shoulder-care', 'Big bodies take a lot of load through the hips, knees and shoulders. This block builds mobility and stability where linemen get hurt most, and strengthens the hamstrings and trunk that keep the base strong all season. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('lb-sideline-sideline-speed', 'Range and pursuit speed for the linebacker. Acceleration and curved-pursuit sprints build the ability to close on ball carriers, while power cleans and plyometrics develop the explosiveness to arrive with force. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('lb-closing-strength-power', 'Strength and explosive power for the hit. Heavy squats and pulls build the base, presses and cleans develop the force needed to shed blockers and finish tackles, and med-ball throws train the hips to explode through contact. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('lb-read-react-agility', 'Read-and-react quickness for the middle of the defense: shuffle and fit mechanics, breaks on the ball from a backpedal, and cut-and-collide preparation that keeps you under control at contact. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('lb-full-field-conditioning', 'Conditioning for a position that covers the full field. Gassers and shuttles build the ability to repeat sideline-to-sideline efforts, and sled work builds the leg endurance to keep hitting late in the game. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('lb-hip-shoulder-care', 'Tackling and pursuit take a toll. Hip and hamstring resilience, shoulder stability for contact, and knee and ankle robustness keep a linebacker on the field through a full season. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('pg-transition-speed', 'Open-court speed for the ball handler: acceleration through the first 20 feet, curved sprints to beat the defense down the floor, and elastic power that lets you change pace without wasting energy. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('pg-finishing-strength', 'Guards need to be strong for their size to absorb contact and finish at the rim. Front squats and hip thrusts build the lower body, upper-body work handles contact, and cleans and depth jumps develop vertical power. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('point-guard-explosiveness', 'First-step quickness and change of direction for the ball handler. On-ball footwork, defensive slides and closeouts, and stop-and-go cutting drills build the ability to shake a defender or stay in front of one. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', 'Point Guard Change-of-Direction Quickness'),
  ('pg-full-court-conditioning', 'Repeat-sprint conditioning for a guard who runs the floor for 30 minutes. Court-line sprints, bike intervals and short repeat sprints build the ability to keep pace with the ball late in the fourth quarter. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('pg-ankle-knee-care', 'Ankle sprains and knee overload are the price of constant cutting. This block builds ankle stiffness and balance, knee robustness, and hip control so the joints can handle the change of direction demands of the position. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('sg-closeout-speed', 'Speed for the perimeter scorer: closing out on shooters, getting to open spots, and outrunning defenders in transition. Short acceleration work, flying sprints and elastic plyometrics. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('sg-vertical-finishing-power', 'Vertical leap and finishing strength for the wing. Heavy squats build the base, reactive plyometrics and cleans convert it into jump height, and upper-body work handles contact at the rim. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('sg-cut-closeout-agility', 'Agility for off-ball cutting and on-ball defense. Sharp cuts to get open, closeouts and defensive slides, and footwork off the catch so you''re balanced and ready to shoot. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('sg-full-court-conditioning', 'Conditioning for a wing who runs off screens and sprints in transition all game. A mix of court sprints, aerobic base work and repeat-effort intervals. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('sg-ankle-knee-care', 'Durability for the perimeter player''s joints: ankle stiffness and balance, knee and quad tendon strength, and hip and trunk control for landing safely after every jump. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('center-rim-to-rim-speed', 'Speed for the big man: rim-running acceleration and first-step burst, elastic ankles and hips, and explosive power so you can outrun the other team''s center down the floor. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('center-post-strength-power', 'Heavy strength for winning position in the paint. Squats and deadlifts for the base, pressing and rowing for post battles, plus vertical power work for rebounding and rim protection. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('center-post-footwork-agility', 'Quick feet for a big body: drop-step and post footwork, defensive slides and hedge-and-recover movement, with lower-body reactivity so you can stay in front of guards on switches. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('center-rebounding-conditioning', 'Conditioning for a post player who battles every possession: sled and carry work for strength endurance, bike intervals to keep the engine running, and repeat-effort work to keep rebounding late. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('center-knee-shoulder-care', 'Big men carry big loads through the knees and back, and overhead work stresses the shoulders. Knee and landing durability, shoulder stability and hip and spine mobility to keep you in the lane. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('forward-explosive-finishing-plan', 'Speed to get in behind and finish. Acceleration out of the first step, top-end sprinting and elastic plyometrics, with hamstring work to keep the legs healthy under high-speed running. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('forward-finishing-power', 'Strength and power for shielding the ball, winning duels and striking with authority. Lower-body lifts for the base, upper-body work for hold-up play, and jumping and rotational power for headers and shots. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('forward-box-movement-agility', 'Movement to lose defenders in the box: check runs, sharp cuts and reactive changes of direction, plus shooting-turn footwork and deceleration control. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('forward-match-day-conditioning', 'Repeat-sprint ability and aerobic base for a forward who makes high-intensity runs all match. Repeat sprints, high-intensity intervals and an aerobic base to recover between efforts. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('forward-hamstring-groin-care', 'Hamstring strains and groin pain are the forward''s occupational hazards. Eccentric hamstring work, adductor strength and hip mobility protect the sprint and the strike. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('midfielder-box-to-box-speed', 'Speed that holds up for 90 minutes: repeated sprint mechanics, top-end running and elastic power for the midfielder who covers every blade of grass. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('midfielder-functional-strength-power', 'Functional strength for winning the midfield battle: single-leg strength for stability, trunk strength for shielding, and explosive lifts and throws for power over the ball. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('midfielder-change-of-direction-agility', 'Agility to receive under pressure, turn away from it and press: turning and receiving footwork, pressing steps and deceleration control. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('soccer-midfielder-engine-builder', 'The engine room. Aerobic base, tempo intervals and match-simulation work build the capacity to run high-intensity for 90 minutes and recover fast between efforts. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('midfielder-hamstring-groin-care', 'Protect the muscles that carry a midfielder through the season: hamstring strength, groin and hip resilience, and core and ankle control. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('defender-recovery-speed', 'Recovery speed to track down runners: backpedal-to-sprint transitions, acceleration and top-end speed, with power and elastic training to close gaps fast. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('defender-aerial-tackling-strength', 'Strength to win aerial duels and tackles: heavy lower-body work, upper-body strength for contact, and jumping and heading power. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('defender-jockey-recovery-agility', 'Agility to stay in front of attackers: jockeying and mirroring, turning and recovering, and stepping and blocking quickly. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('defender-ninety-minute-conditioning', 'Conditioning to stay sharp for a full match: aerobic base, tempo intervals and repeat efforts to keep recovery sprints crisp in the final minutes. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('defender-hamstring-groin-care', 'Keep defenders available: hamstring and posterior-chain strength, groin and hip resilience, and knee and ankle durability for a season of duels and recovery runs. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('goalkeeper-reaction-speed', 'Reaction and short-burst speed for the keeper: first-step reaction to shots, explosive feet and hands, and power to close down angles and get off the line. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('goalkeeper-diving-catching-power', 'Strength and power for diving, catching and distributing. Lower-body strength for explosive dives, upper-body strength for catching and punching, and jumping power for high balls. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('goalkeeper-lateral-dive-agility', 'Lateral quickness and dive mechanics: footwork to set your feet, dive progressions, and recover-and-reset drills for the second save. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('goalkeeper-match-sharpness-conditioning', 'Conditioning for a position of long stillness and sudden effort: repeat explosive efforts, an aerobic base to speed recovery, and intervals to stay sharp late in the match. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('goalkeeper-shoulder-wrist-care', 'The keeper''s shoulders, wrists and hips take repeated impact from dives, catches and punches. This block builds shoulder stability, wrist and forearm resilience, and hip and landing mechanics. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('pitcher-baserunning-speed', 'Leg speed and explosiveness for the pitcher: acceleration mechanics, elastic power and strength-speed work that also supports the lower-half drive on the mound. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('pitcher-lower-half-drive-power', 'Velocity comes from the ground up. Squats and single-leg work build the drive leg, rotational medicine-ball training teaches hip-to-shoulder sequencing, and scapular strength keeps the arm healthy while you throw harder. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('pitcher-fielding-pickoff-agility', 'Movement for the fifth infielder: fielding footwork, pickoff and covering moves, and balance and deceleration control. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('pitcher-bullpen-stamina', 'Conditioning to repeat quality pitches deep into outings and recover between them. Aerobic base, tempo work and leg-and-core endurance, without taxing the arm. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('pitcher-arm-care-mobility', 'The pitcher''s daily insurance policy: rotator cuff and scapular strength, thoracic and hip mobility for a free delivery, and forearm and elbow resilience. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('infielder-first-step-burst', 'Burst for the infielder: steals and first-step reactions, home-to-first speed, and elastic power for getting to balls and around the bases. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('infielder-throwing-lower-power', 'Power for the swing and the throw: lower-body strength, rotational power through the hips and trunk, and upper-body strength for a durable arm. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('infielder-lateral-quickness-plan', 'Range and reaction at the six-foot level: shuffle and glove-side footwork, reactive range work, and the footwork that goes into turning double plays. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('infielder-nine-inning-conditioning', 'Conditioning to stay sharp for nine innings in the field and on the bases: tempo running, intervals and aerobic base work to keep reaction and recovery quick. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('infielder-hip-shoulder-care', 'Durability for the throwing arm and the hips that carry an infielder through repeated fielding and throwing: shoulder stability, hip mobility, and core and ankle control. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null),
  ('outfielder-route-to-ball-speed', 'Get to balls before they drop: acceleration off the crack of the bat, curved and angled route running, top-end speed and elastic power. Progression: weeks 1-2 groove mechanics at about 90% effort with full rest; weeks 3-4 add resisted and flying volume. Stop a sprint set the moment speed drops.', null),
  ('outfielder-throwing-power', 'Arm strength and lower-body power for the outfielder: strong legs to drive the throw, rotational power through the trunk, and upper-body strength for a durable arm. Progression: weeks 1-2 leave 2 reps in reserve; weeks 3-4 add 2.5-5% load or a rep once every set is clean. Move power work fast and stop when bar speed fades.', null),
  ('outfielder-reactive-agility', 'Reaction and jump: the first read off the bat, angle routes and quick changes of direction, and the deceleration to set your base for the throw. Progression: weeks 1-2 learn each pattern under control; weeks 3-4 add reactive cues (a partner call or visual signal) and shorten rest.', null),
  ('outfielder-conditioning', 'Conditioning for long stretches of standing followed by full-speed sprints: repeat sprint work, aerobic base and intervals to run down a fly ball in the ninth as fast as in the first. Progression: weeks 1-2 build the aerobic base at a controlled pace; weeks 3-4 trim rest by 10-15 seconds and add one interval per block.', null),
  ('outfielder-shoulder-hamstring-care', 'Protect the arm and the wheels: shoulder and scapular stability for throwing, hamstring strength for high-speed running, and hip and ankle mobility. Progression: low load, high control, never train through sharp pain. In weeks 3-4 slow the lowering phase to 3 seconds and add a set.', null)
  ) as v(plan_slug, description, new_name)
  where p.slug = v.plan_slug;
  get diagnostics n = row_count;
  if n <> 70 then raise exception 'expected 70 plans updated, updated %', n; end if;

  -- 5. remove the superseded workouts, but only if nothing references them
  delete from public.workouts w
  where w.id = any (old_ids)
    and not exists (select 1 from public.plan_workouts x where x.workout_id = w.id)
    and not exists (select 1 from public.progress_logs l where l.workout_id = w.id);
end $$;
-- Post-conditions: fail loudly rather than leave the library half-migrated.
do $$
begin
  if exists (select 1 from public.plans p where (select count(distinct workout_id) from public.plan_workouts where plan_id = p.id) < 3) then
    raise exception 'a plan has fewer than 3 distinct workouts';
  end if;
  if exists (select 1 from public.workouts w where not exists (select 1 from public.workout_exercises we where we.workout_id = w.id)) then
    raise exception 'a workout has no exercises';
  end if;
  if exists (select 1 from public.plan_workouts pw where not exists (select 1 from public.workouts w where w.id = pw.workout_id)) then
    raise exception 'a plan_workouts row points at a missing workout';
  end if;
end $$;
